import{_ as t,o as i,c as a,a0 as n}from"./chunks/framework.DScjKhBS.js";const y=JSON.parse('{"title":"Agency Project Lifecycle — AI Opportunity Analysis","description":"Research analysis of the standard design-and-build agency project flow from estimation through delivery, identifying improvement points for AI and new tooling.","frontmatter":{"layout":"doc","title":"Agency Project Lifecycle — AI Opportunity Analysis","description":"Research analysis of the standard design-and-build agency project flow from estimation through delivery, identifying improvement points for AI and new tooling."},"headers":[],"relativePath":"reports/agency-project-lifecycle/index.md","filePath":"reports/agency-project-lifecycle/index.md"}'),o={name:"reports/agency-project-lifecycle/index.md"};function r(l,e,s,c,d,p){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="agency-project-lifecycle-—-ai-opportunity-analysis" tabindex="-1">Agency Project Lifecycle — AI Opportunity Analysis <a class="header-anchor" href="#agency-project-lifecycle-—-ai-opportunity-analysis" aria-label="Permalink to &quot;Agency Project Lifecycle — AI Opportunity Analysis&quot;">​</a></h1><p>An analysis of the standard design-and-build project flow used by most agencies (including Elixirr Digital), mapped phase-by-phase against current AI and tooling opportunities. The goal: identify where existing workflows leak time, quality, or margin — and where new tooling can close those gaps.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>The lifecycle covered runs from <strong>pre-sale estimation</strong> through <strong>client handover and support</strong>. This is deliberately broader than the existing <a href="./reports/ai-augmented-dev-pipeline/">AI-Augmented Dev Pipeline</a> and <a href="./reports/dark-factory/">Dark Factory</a> reports, which focus primarily on the build phase. Here we examine the full chain:</p><ol><li>Estimation and scoping</li><li>Briefing and discovery</li><li>Information architecture and content planning</li><li>Design (UX/UI)</li><li>Technical specification and planning</li><li>Build (development)</li><li>Content population and migration</li><li>QA and testing</li><li>Client training</li><li>Delivery (launch)</li><li>Post-launch support and governance</li></ol><h2 id="report-sections" tabindex="-1">Report sections <a class="header-anchor" href="#report-sections" aria-label="Permalink to &quot;Report sections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>Description</th></tr></thead><tbody><tr><td><a href="./reports/agency-project-lifecycle/01-standard-workflow.html">1. Standard Agency Workflow</a></td><td>The canonical 11-phase flow most agencies follow, with typical timelines and deliverables</td></tr><tr><td><a href="./reports/agency-project-lifecycle/02-pain-points.html">2. Pain Points and Waste Map</a></td><td>Where time, quality, and margin are lost — phase by phase</td></tr><tr><td><a href="./reports/agency-project-lifecycle/03-ai-opportunity-map.html">3. AI and Tooling Opportunity Map</a></td><td>Phase-by-phase analysis of what AI or new tooling can improve, with maturity ratings</td></tr><tr><td><a href="./reports/agency-project-lifecycle/04-recommendations.html">4. Prioritised Recommendations</a></td><td>Ranked interventions by impact, effort, and readiness for an Elixirr Digital context</td></tr></tbody></table><p>Start with <a href="./reports/agency-project-lifecycle/01-standard-workflow.html">Standard Agency Workflow</a> for the baseline, then move to the opportunity map.</p>',8)])])}const f=t(o,[["render",r]]);export{y as __pageData,f as default};
